referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const calc = (name) => {
    const v = d.cells[name] ?? 0;
    if (typeof v === "number") return v;
    const val = (x) => (typeof x === "number" ? x : calc(x));
    let out = val(v[0]);
    for (let i = 1; i < v.length; i += 2) {
      const x = val(v[i + 1]);
      out = v[i] === "+" ? out + x : v[i] === "-" ? out - x : out * x;
    }
    return out;
  };
  return d.queries.map(calc);
}

